1	/**
2	 * argparse.mjs — a faithful port of the `argparse.ArgumentParser` behaviour that
3	 * `test7.py` exercises, reconstructed from the reference executable.
4	 *
5	 * The parts that matter (each verified against `/workspace/dataset/test7_executable`):
6	 *
7	 *   * `--a VALUE` and `--a=VALUE`, in any order, last occurrence winning
8	 *   * prefix abbreviation is on: `--h` and `--he` both resolve to `--help`,
9	 *     while `--ab` matches nothing because it is not a prefix of `--a`
10	 *   * a value beginning with `-` is accepted only when it looks like a negative
11	 *     number under `^-\d+$|^-\d*\.\d+$`, or contains a space, or is a bare `-`.
12	 *     So `--a -5`, `--a -.5`, `--a -` and `--a '- x'` all work, while `--a -1.5e3`,
13	 *     `--a -1.` and `--a -5x` fail with "expected one argument"
14	 *   * `--` stops option parsing but, because this parser declares no positional
15	 *     arguments, is itself left behind and reported among the unrecognized
16	 *     arguments — `--a 1 --b 2 --` errors with "unrecognized arguments: --"
17	 *   * missing-required is reported *before* unrecognized, because the former is
18	 *     raised inside `parse_known_args` and the latter by `parse_args`
19	 *   * `-h` fires the moment it is reached, so `--a 1 --b 2 -h` still prints help
20	 *     and exits 0
21	 */
22	
23	import { SystemExit } from './pyerrors.mjs';
24	import { writeStdout, writeStderr } from './pyio.mjs';
25	import { wrapText } from './textwrap.mjs';
26	
27	/** `argparse.ArgumentParser._negative_number_matcher` */
28	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
29	
30	/**
31	 * `prog` defaults to `os.path.basename(sys.argv[0])`. The reference build is a
32	 * frozen binary named `test7_executable`, and its usage/error text is the output
33	 * this port is measured against, so that name is the default here. Override it
34	 * with the `ARGPARSE_PROG` environment variable if a different `prog` is wanted.
35	 */
36	const DEFAULT_PROG = 'test7_executable';
37	
38	class ArgumentError extends Error {
39	  constructor(action, message) {
40	    const name = action && action.optionStrings.length ? action.optionStrings.join('/') : null;
41	    super(name ? `argument ${name}: ${message}` : message);
42	    this.name = 'ArgumentError';
43	  }
44	}
45	
46	/** `argparse.HelpFormatter`, enough of it to reproduce `--help` byte for byte. */
47	class HelpFormatter {
48	  constructor(prog, width) {
49	    this.prog = prog;
50	    this.indentIncrement = 2;
51	    this.width = width;
52	    // HelpFormatter.__init__: min(max_help_position, max(width - 20, indent*2))
53	    this.maxHelpPosition = Math.min(24, Math.max(this.width - 20, this.indentIncrement * 2));
54	  }
55	
56	  /** Metavar for an optional: explicit metavar, else `dest.upper()`. */
57	  static formatMetavar(action) {
58	    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
59	    return action.dest.toUpperCase();
60	  }
61	
62	  /** `[-h]`, `--a A` — one wrappable unit per action. */
63	  static usagePart(action) {
64	    const optionString = action.optionStrings[0];
65	    const body =
66	      action.nargs === 0 ? optionString : `${optionString} ${HelpFormatter.formatMetavar(action)}`;
67	    return action.required ? body : `[${body}]`;
68	  }
69	
70	  /** `-h, --help`, `--a A` — the left column of the options list. */
71	  static invocation(action) {
72	    if (action.nargs === 0) return action.optionStrings.join(', ');
73	    const metavar = HelpFormatter.formatMetavar(action);
74	    return action.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
75	  }
76	
77	  /**
78	   * `_format_usage`. When the one-line form does not fit, argparse breaks the
79	   * usage into per-action parts and re-flows them; a long `prog` (more than 75%
80	   * of the text width once the prefix is added) is placed on its own line.
81	   */
82	  formatUsage(actions) {
83	    const prefix = 'usage: ';
84	    const parts = actions.map((action) => HelpFormatter.usagePart(action));
85	    let usage = [this.prog, parts.join(' ')].filter((piece) => piece !== '').join(' ');
86	
87	    const textWidth = this.width;
88	    if (prefix.length + usage.length > textWidth) {
89	      const getLines = (items, indent, linePrefix) => {
90	        const lines = [];
91	        let line = [];
92	        let lineLen = (linePrefix !== undefined ? linePrefix.length : indent.length) - 1;
93	        for (const part of items) {
94	          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
95	            lines.push(indent + line.join(' '));
96	            line = [];
97	            lineLen = indent.length - 1;
98	          }
99	          line.push(part);
100	          lineLen += 1 + part.length;
101	        }
102	        if (line.length > 0) lines.push(indent + line.join(' '));
103	        if (linePrefix !== undefined && lines.length > 0) {
104	          lines[0] = lines[0].slice(indent.length);
105	        }
106	        return lines;
107	      };
108	
109	      // This parser declares only optionals, so there is no positional group to
110	      // flow after them; `posParts` is kept explicit to mirror argparse's shape.
111	      const optParts = parts;
112	      const posParts = [];
113	
114	      let lines;
115	      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
116	        // Short prog: the first usage parts share its line.
117	        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
118	        if (optParts.length > 0) {
119	          lines = getLines([this.prog, ...optParts], indent, prefix);
120	          lines.push(...getLines(posParts, indent));
121	        } else if (posParts.length > 0) {
122	          lines = getLines([this.prog, ...posParts], indent, prefix);
123	        } else {
124	          lines = [this.prog];
125	        }
126	      } else {
127	        // Long prog: it gets a line of its own.
128	        const indent = ' '.repeat(prefix.length);
129	        lines = getLines([...optParts, ...posParts], indent);
130	        if (lines.length > 1) {
131	          lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
132	        }
133	        lines = [this.prog, ...lines];
134	      }
135	      usage = lines.join('\n');
136	    }
137	
138	    return `${prefix}${usage}\n`;
139	  }
140	
141	  /** `_format_action` for every action, under a single "options:" section. */
142	  formatOptionsSection(actions) {
143	    const invocations = actions.map((action) => HelpFormatter.invocation(action));
144	    const actionMaxLength = Math.max(0, ...invocations.map((text) => text.length)) + this.indentIncrement;
145	    const helpPosition = Math.min(actionMaxLength + 2, this.maxHelpPosition);
146	    const helpWidth = Math.max(this.width - helpPosition, 11);
147	    const actionWidth = helpPosition - this.indentIncrement - 2;
148	
149	    let out = 'options:\n';
150	    actions.forEach((action, index) => {
151	      const header = invocations[index];
152	      if (!action.help) {
153	        out += ' '.repeat(this.indentIncrement) + header + '\n';
154	        return;
155	      }
156	      const helpLines = wrapText(action.help, helpWidth);
157	      if (header.length <= actionWidth) {
158	        out +=
159	          ' '.repeat(this.indentIncrement) +
160	          header.padEnd(actionWidth) +
161	          '  ' +
162	          (helpLines[0] || '') +
163	          '\n';
164	        for (const line of helpLines.slice(1)) out += ' '.repeat(helpPosition) + line + '\n';
165	      } else {
166	        out += ' '.repeat(this.indentIncrement) + header + '\n';
167	        for (const line of helpLines) out += ' '.repeat(helpPosition) + line + '\n';
168	      }
169	    });
170	    return out;
171	  }
172	}
173	
174	/** `argparse.Namespace` */
175	export class Namespace {
176	  constructor(values = {}) {
177	    Object.assign(this, values);
178	  }
179	}
180	
181	export class ArgumentParser {
182	  constructor(options = {}) {
183	    this.prog = options.prog !== undefined ? options.prog : process.env.ARGPARSE_PROG || DEFAULT_PROG;
184	    this.prefixChars = options.prefixChars || '-';
185	    this.allowAbbrev = options.allowAbbrev !== false;
186	    this.addHelp = options.addHelp !== false;
187	
188	    this.actions = [];
189	    this.optionStringActions = new Map();
190	    // Set when an option string itself looks like a negative number, which
191	    // flips how `-5`-style values are interpreted.
192	    this.hasNegativeNumberOptionals = false;
193	
194	    if (this.addHelp) {
195	      this.addArgument(['-h', '--help'], {
196	        action: 'help',
197	        nargs: 0,
198	        help: 'show this help message and exit',
199	      });
200	    }
201	  }
202	
203	  /**
204	   * Terminal width, mirroring `shutil.get_terminal_size().columns - 2`:
205	   * `COLUMNS` wins when it parses to a positive integer, otherwise the real
206	   * terminal size, otherwise the 80-column fallback (the case that applies
207	   * whenever output is redirected, i.e. under any test harness).
208	   */
209	  get formatterWidth() {
210	    const fromEnv = parseInt(process.env.COLUMNS || '', 10);
211	    if (Number.isFinite(fromEnv) && fromEnv > 0) return fromEnv - 2;
212	    const tty = process.stdout && process.stdout.isTTY ? process.stdout.columns : 0;
213	    return (tty > 0 ? tty : 80) - 2;
214	  }
215	
216	  /** `add_argument('--a', type=str, required=True)` */
217	  addArgument(optionStrings, options = {}) {
218	    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
219	    const longest = strings.find((s) => s.startsWith(this.prefixChars.repeat(2))) || strings[0];
220	    const dest = options.dest || longest.replace(/^-+/, '').replace(/-/g, '_');
221	
222	    const action = {
223	      optionStrings: strings,
224	      dest,
225	      required: options.required === true,
226	      nargs: options.nargs !== undefined ? options.nargs : null,
227	      metavar: options.metavar !== undefined ? options.metavar : null,
228	      help: options.help !== undefined ? options.help : null,
229	      action: options.action || 'store',
230	      defaultValue: options.default !== undefined ? options.default : null,
231	    };
232	
233	    this.actions.push(action);
234	    for (const optionString of strings) {
235	      this.optionStringActions.set(optionString, action);
236	      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals = true;
237	    }
238	    return action;
239	  }
240	
241	  formatUsage() {
242	    return new HelpFormatter(this.prog, this.formatterWidth).formatUsage(this.actions);
243	  }
244	
245	  formatHelp() {
246	    const formatter = new HelpFormatter(this.prog, this.formatterWidth);
247	    return `${formatter.formatUsage(this.actions)}\n${formatter.formatOptionsSection(this.actions)}`;
248	  }
249	
250	  printHelp() {
251	    writeStdout(this.formatHelp());
252	  }
253	
254	  /** `parser.error(message)` — usage on stderr, then `sys.exit(2)`. */
255	  error(message) {
256	    writeStderr(this.formatUsage());
257	    writeStderr(`${this.prog}: error: ${message}\n`);
258	    throw new SystemExit(2);
259	  }
260	
261	  /**
262	   * `_parse_optional`. Returns `null` when the string is a positional, or
263	   * `[action, optionString, sep, explicitArg]` where `action` is `null` for an
264	   * option-looking string that matches nothing.
265	   *
266	   * `sep` records *how* an explicit argument was attached: `'='` when it was
267	   * split off an `=`, `''` when it was concatenated onto a single-dash option
268	   * (`-hx`), and `null` when there is none. The distinction is load-bearing —
269	   * `-hx` chains into another short option while `-h=x` is an error.
270	   */
271	  parseOptional(argString) {
272	    if (argString === '') return null;
273	    if (!this.prefixChars.includes(argString[0])) return null;
274	
275	    if (this.optionStringActions.has(argString)) {
276	      return [this.optionStringActions.get(argString), argString, null, null];
277	    }
278	    if (argString.length === 1) return null; // a bare "-" is a positional
279	
280	    const equalsAt = argString.indexOf('=');
281	    if (equalsAt !== -1) {
282	      const optionString = argString.slice(0, equalsAt);
283	      const explicitArg = argString.slice(equalsAt + 1);
284	      if (this.optionStringActions.has(optionString)) {
285	        return [this.optionStringActions.get(optionString), optionString, '=', explicitArg];
286	      }
287	    }
288	
289	    const tuples = this.getOptionTuples(argString);
290	    if (tuples.length > 1) {
