// ascii, incl. escapes and quotes
for (const c of ['a', 'b', 'z', 'A', 'Z', '0', '9', '"', '\\', '/', ' ', '~', '!']) alphabet.push(Buffer.from(c));
for (const b of [0x01, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1f, 0x7f]) alphabet.push(Buffer.from([b]));
// multi-byte utf-8
for (const s of ['é', 'Ā', '日', '', '', '', '', '\u{1F600}', '\u{10FFFF}', '\u{FFFF}', '\u{10000}']) {
  alphabet.push(Buffer.from(s, 'utf8'));
}
// invalid bytes
for (const b of [0x80, 0x81, 0xbf, 0xc0, 0xc1, 0xed, 0xf5, 0xfe, 0xff]) alphabet.push(Buffer.from([b]));

function randArg() {
  const len = rnd(7);
  const parts = [];
  for (let i = 0; i < len; i++) parts.push(alphabet[rnd(alphabet.length)]);
  return Buffer.concat(parts);
}

const cases = [];
for (let i = 0; i < 700; i++) {
  const a = randArg();
  const b = randArg();
  cases.push({ argv: ['--a', a, '--b', b], label: `a=${a.toString('hex')} b=${b.toString('hex')}` });
}
process.exit((await runSuite('rand', cases, 16)) ? 1 : 0);
